<script>const campCandidate=document.getElementById('candidate-key');const campPlayer=document.getElementById('approve-player-id');const clearCampIdentityReview=()=>{const confirmation=campCandidate?.form.querySelector('[name="identity_confirmed"]');if(confirmation)confirmation.checked=false;};campCandidate?.addEventListener('change',event=>{if(campPlayer)campPlayer.value=event.target.selectedOptions[0]?.dataset.player||'';clearCampIdentityReview();});campPlayer?.addEventListener('change',clearCampIdentityReview);</script>
<script>document.querySelector('[data-camp-add-division]')?.addEventListener('click',()=>{const list=document.querySelector('[data-camp-divisions]');if(list.children.length>=30)return;const row=list.firstElementChild.cloneNode(true);const index=list.children.length;row.querySelectorAll('input,select,label').forEach(el=>{for(const attr of ['name','id','for'])if(el.hasAttribute(attr))el.setAttribute(attr,el.getAttribute(attr).replace(/divisions\[\d+\]/,'divisions['+index+']').replace(/division-\d+-/,'division-'+index+'-'));if(el.tagName==='INPUT'){el.value='';el.removeAttribute('readonly');}if(el.tagName==='SELECT')el.value='0';});list.append(row);});</script>
<?php $__env->stopSection(); ?>

